    {n:"Conversione km/h - m/s", f:"v_{[\\mathrm{m/s}]}=\\frac{v_{[\\mathrm{km/h}]}}{3{,}6}"},
    {n:"Accelerazione", f:"a=\\frac{\\Delta v}{\\Delta t}"},
    {n:"Moto uniformemente accelerato", f:"s=s_0+v_0t+\\tfrac{1}{2}at^2"}
